import pandas as pd
import os

# --- CONFIGURATION ---
# Path to the CSV file generated by your previous script
CSV_PATH = r"\\FS19\HomeDir\129963\Desktop\DR2\4 Coding\sample_data\vin93_soh_results\soh_events.csv"
RATED_AH = 155.0

def check_anomalies(file_path):
    if not os.path.exists(file_path):
        print(f"File not found: {file_path}")
        return

    # Load the results
    df = pd.read_csv(file_path)
    
    # Filter rows where dQ_ah > 155 OR C_A_ah > 155
    # (Using fillna to ignore NaN values in C_A_ah)
    anomalies = df[
        (df["dQ_ah"] > RATED_AH) | 
        (df["C_A_ah"].fillna(0) > RATED_AH)
    ]
    
    if anomalies.empty:
        print("✅ No anomalies found. No event exceeded 155 Ah.")
        return

    print(f"⚠️ Found {len(anomalies)} anomalous events exceeding {RATED_AH} Ah:\n")
    
    # Select the most important columns to display
    cols_to_show = [
        "event", "odo_km", "dur_s", "dsoc", "dQ_ah", "C_A_ah", 
        "i_mean", "vmax_end", "status", "missing_frac"
    ]
    
    # Print the table with nice formatting
    pd.set_option('display.max_columns', None)
    pd.set_option('display.width', 1000)
    pd.set_option('display.float_format', lambda x: f'{x:.2f}')
    
    print(anomalies[cols_to_show].to_string(index=False))
    print("\n" + "="*80)
    
    # Analyze WHY they happened
    print("🔍 ANALYSIS OF ANOMALIES:")
    for idx, row in anomalies.iterrows():
        print(f"\nEvent {int(row['event'])}:")
        print(f"  - Mean Current: {row['i_mean']:.2f} A")
        print(f"  - Missing Data Fraction: {row['missing_frac']*100:.2f}%")
        print(f"  - Max Voltage at End: {row['vmax_end']} V")
        
        if row['i_mean'] > 200:
            print("   CAUSE: Sensor error code (e.g., 1000 A).")
        elif row['missing_frac'] > 0.10:
            print("   CAUSE: Huge data gaps. The integration assumes current stayed constant.")
        elif row['dsoc'] <= 0:
            print("   CAUSE: SOC did not increase (dsoc <= 0), but current was integrated.")
        else:
            print("   CAUSE: Unknown. Check raw data.")
    print("="*80)

if __name__ == "__main__":
    check_anomalies(CSV_PATH)